float M  = A;
float T0 = 0.0;           
float K  = U*U - T0*T0;
float r  = solveKruskalR(K, M);
float gXX = (32.0*M*M*M / r) * exp(-r/(2.0*M));
float gpp = r * r;
return mat3(gXX, 0.0, 0.0,
            0.0, gpp, 0.0,
            0.0, 0.0, 1.0);

